import React, { useEffect, useState } from "react";
import { getDailyBoxOffice, getMovieDetail } from "../api/boxofficeApi";
import { getPosterFromTMDB } from "../api/tmdbApi";
import MovieCard from "../components/MovieCard"; // MovieCard 컴포넌트가 있다고 가정

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchBoxOffice = async () => {
      setLoading(true);
      try {
        const today = new Date();
        today.setDate(today.getDate() - 1);
        const targetDt = `${today.getFullYear()}${String(today.getMonth() + 1).padStart(2, "0")}${String(today.getDate()).padStart(2, "0")}`;

        const boxOfficeList = await getDailyBoxOffice(targetDt);

        const enrichedMovies = await Promise.all(
          boxOfficeList.map(async (movie, index) => {
            const year = movie.openDt?.substring(0, 4) || "";
            
            // 상세 정보에서 감독 이름과 '영문 제목' 추출
            const detail = await getMovieDetail(movie.movieCd);
            const directorName = detail.directors?.[0]?.peopleNm;
            const movieNmEn = detail.movieNmEn; // 영문 제목 추가

            // getPosterFromTMDB에 영문 제목도 함께 전달
            const posterUrl = await getPosterFromTMDB(movie.movieNm, year, {
              directorName,
              movieNmEn, // 옵션으로 전달
            });
            
            // MovieCard에 전달할 줄바꿈이 있는 설명 포맷팅
            const description = [
                `📅 개봉일: ${movie.openDt || "N/A"}`,
                `👥 누적 관객: ${parseInt(movie.audiAcc).toLocaleString()}명`,
                `🎟️ 일일 관객: ${parseInt(movie.audiCnt).toLocaleString()}명`,
                `🎬 스크린 수: ${movie.scrnCnt || "N/A"}`
            ];

            return {
              id: movie.movieCd, // 고유한 movieCd를 id로 사용
              title: movie.movieNm,
              poster_path: posterUrl || "https://via.placeholder.com/120x170?text=No+Image",
              description, // 배열 형태로 전달
            };
          })
        );
        setMovies(enrichedMovies);
      } catch (error) {
        console.error("박스오피스 데이터를 불러오는 데 실패했습니다:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchBoxOffice();
  }, []);

  if (loading) return <div>로딩 중...</div>;

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>📊 일별 박스오피스</h1>
      <div style={styles.movieGrid}>
        {movies.map((movie) => (
          // MovieCard 컴포넌트는 description 배열을 받아 처리하도록 수정 필요
          <MovieCard key={movie.id} movie={movie} /> 
        ))}
      </div>
    </div>
  );
}

const styles = {
  container: {
    width: "100%",
    maxWidth: "1200px",
    margin: "0 auto",
    padding: "2rem",
    boxSizing: "border-box",
  },
  title: {
    fontSize: "2.5rem",
    textAlign: "center",
    marginBottom: "3rem",
    fontWeight: "bold",
  },
  movieGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(3, 1fr)",
    columnGap: "2rem",
    rowGap: "3rem",
  },
};

export default HomePage;
